                return
            if depth < 0:
                return
            first, rest = subgoals[0], subgoals[1:]
            _prove_goal(first, rest, depth, trail)

        def _prove_goal(target: Proposition, remaining: List[Proposition], depth: int, trail: List[Proposition]):
            key = (target.predicate, target.args)
